INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(7201, '1 Samuel 19:2', '1 Samuel', 19, 2, '&nbsp;نو يونتن داؤد ته ووئيل، ”زما پلار تا قتل کول غواړى. نو مِهربانى وکړه چې سبا سحر د ځان حِفاظت وکړه، په يو محفوظ ځائ کښې پټ شه او هلته ايسار شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7202, '1 Samuel 19:3', '1 Samuel', 19, 3, '&nbsp;چې په کوم پټى کښې تۀ پټ يې نو زۀ به هلته لاړ شم او د خپل پلار سره به ودرېږم او زۀ به د هغۀ سره ستا په حقله خبره وکړم. کۀ ما ته د څۀ پته ولګى نو زۀ به تا خبر کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7203, '1 Samuel 19:4', '1 Samuel', 19, 4, '&nbsp;يونتن ساؤل ته د داؤد صِفت وکړو او ورته يې ووئيل، ”بادشاه سلامت دې د خپل خِدمت کوونکى داؤد خِلاف غلط کار نۀ کوى. هغۀ تا ته هيڅ نقصان نۀ دے رسولے. هغۀ چې ستا څۀ مدد هم کولے شو نو هغۀ هغه تل کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7204, '1 Samuel 19:5', '1 Samuel', 19, 5, '&nbsp;کله چې هغۀ جوليت وژلو نو هغۀ خپل ژوند په خطره کښې واچولو او مالِک خُدائ د بنى اِسرائيلو دپاره يوه لويه فتح وموندله. کله چې تا هغه فتح وليده نو تۀ خوشحاله شوې. نو بيا تۀ ولې د يو بې‌ګناه سړى سره بد کوې او بغېر د څۀ وجې داؤد وژنې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7205, '1 Samuel 19:6', '1 Samuel', 19, 6, '&nbsp;نو ساؤل د يونتن خبره ومنله او د ژوندى مالِک خُدائ په نوم يې قسم وکړو چې داؤد به نۀ وژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7206, '1 Samuel 19:7', '1 Samuel', 19, 7, '&nbsp;نو يونتن داؤد راوغوښتو او هر څۀ يې ورته ووئيل، بيا يې هغه ساؤل له بوتلو او داؤد د مخکښې په شان په دربار کښې خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7207, '1 Samuel 19:8', '1 Samuel', 19, 8, '&nbsp;د فلستيانو سره بيا جنګ شروع شو. داؤد په هغوئ باندې د دومره لوئ طاقت سره حمله وکړه چې هغوئ وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7208, '1 Samuel 19:9', '1 Samuel', 19, 9, '&nbsp;يوه ورځ د مالِک خُدائ رالېږلے شوى پېرى ساؤل ونيولو. هغه په خپل کور کښې ناست وو او نېزه يې په لاس کښې وه او داؤد هلته خپله بينجو غږوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7209, '1 Samuel 19:10', '1 Samuel', 19, 10, '&nbsp;ساؤل کوشش وکړو چې داؤد د نېزې په سر باندې د دېوال سره ونښلوى، خو داؤد د هغه ځائ نه ټوپ کړل او نېزه په دېوال کښې ونښتله. په هغه شپه داؤد منډه کړه او وتښتېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7210, '1 Samuel 19:11', '1 Samuel', 19, 11, '&nbsp;بيا ساؤل يو څو سړى ولېږل چې د داؤد کور ولټوى او په ورپسې سحر يې ووژنى. د داؤد ښځې ميکل هغۀ له خبردارے ورکړو او ورته يې ووئيل، ”کۀ تۀ نن شپه لا نۀ ړې نو سبا به مړ يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7211, '1 Samuel 19:12', '1 Samuel', 19, 12, '&nbsp;هغې د يوې کړکۍ نه هغه کوز کړو او هغه په منډه منډه وتښتېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7212, '1 Samuel 19:13', '1 Samuel', 19, 13, '&nbsp;بيا هغې د کور هغه بُت واخستو، په کټ کښې يې واچولو، د دې په سر يې د چېلو وړۍ واچولې او په يوه کپړه باندې يې پټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7213, '1 Samuel 19:14', '1 Samuel', 19, 14, '&nbsp;کله چې د ساؤل سړى د داؤد په بوتلو پسې راغلل، نو ميکل هغوئ ته ووئيل چې هغه بيمار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7214, '1 Samuel 19:15', '1 Samuel', 19, 15, '&nbsp;خو ساؤل هغوئ ورولېږل چې داؤد راولى. هغۀ هغوئ له حُکم ورکړو چې، ”هغه په خپل کټ کښې دلته راوړئ، چې وې وژنم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7215, '1 Samuel 19:16', '1 Samuel', 19, 16, '&nbsp;هغوئ دننه لاړل او په کټ کښې يې هغه د کور والا بُت وليدو چې په سر باندې يې د چېلو وړۍ وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7216, '1 Samuel 19:17', '1 Samuel', 19, 17, '&nbsp;ساؤل د ميکل نه تپوس وکړو، ”تا زما سره داسې دوکه ولې وکړه او زما دشمن سره دې په تښتېدو کښې مدد ولې وکړو؟“ هغې ورته په جواب کښې ووئيل، ”هغۀ ما ته ووئيل چې کۀ په تښتېدو کښې مې د هغۀ مدد ونۀ کړو نو هغه به مې ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7217, '1 Samuel 19:18', '1 Samuel', 19, 18, '&nbsp;نو داؤد وتښتېدو او په راما کښې سموئيل له لاړو او هغه هر څۀ يې ورته وفرمائيل چې ساؤل ورسره کړى وُو. بيا هغه د سموئيل سره نَيوت ته لاړو او دواړه هلته ايسار شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7218, '1 Samuel 19:19', '1 Samuel', 19, 19, '&nbsp;ساؤل خبر شو چې داؤد په راما کښې په نَيوت کښې دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7219, '1 Samuel 19:20', '1 Samuel', 19, 20, '&nbsp;نو هغۀ يو څو سړى ورولېږل چې وې نيسى. نو هغوئ وليدل چې د پېغمبرانو يوې قبيلې پېغام ورکولو چې د خپل مشر سموئيل سره ولاړ وُو. بيا د خُدائ پاک روح د ساؤل سړى ونيول او هغوئ هم پېغام ورکول شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7220, '1 Samuel 19:21', '1 Samuel', 19, 21, '&nbsp;کله چې ساؤل د دې نه خبر شو، نو هغۀ نور پېغام وړُونکى ورولېږل او هغوئ هم پېشګوئې ورکوله. هغۀ په درېم ځل پېغام وړُونکى ولېږل او بيا د هغوئ سره هم هغه شان وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7221, '1 Samuel 19:22', '1 Samuel', 19, 22, '&nbsp;بيا هغه په خپله راما ته روان شو. کله چې هغه په سيکو کښې لوئ کوهى ته راغلو او هغۀ تپوس وکړو چې سموئيل او داؤد چرته دى نو ورته ووئيلے شول چې هغوئ په نَيوت کښې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7222, '1 Samuel 19:23', '1 Samuel', 19, 23, '&nbsp;چې کله هغه هلته روان وو، نو د خُدائ پاک روح هغه هم ونيولو او هغۀ تر نَيوت پورې په ټوله لار کښې پېشګوئې ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7223, '1 Samuel 19:24', '1 Samuel', 19, 24, '&nbsp;هغۀ خپلې جامې وويستلې او د سموئيل په مخکښې يې پېشګوئې ورکول شروع کړل او په هغه ټوله ورځ او ټوله شپه بربنډ پروت وو. (نو دا ځکه دا متل شروع شو، ”ساؤل پېغمبر جوړ شوے دے څۀ؟“)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7224, '1 Samuel 20:1', '1 Samuel', 20, 1, '&nbsp;بيا داؤد په راما کښې د نَيوت نه وتښتېدو او يونتن له لاړو. داؤد ترې نه تپوس وکړو، ”ما څۀ کړى دى، ما څۀ جرم کړے دے؟ ما ستا پلار سره څۀ بد کړى دى چې هغه ما وژنى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7225, '1 Samuel 20:2', '1 Samuel', 20, 2, '&nbsp;يونتن ورته ووئيل، ”خُدائ دې نۀ کړى چې تۀ مړ شې. زما پلار چې څۀ هم کوى نو هغه ما ته وائى، هغه وړه او غټه يوه خبره هم زما نه نۀ پټوى. داسې نۀ شى کېدے چې هغه تا ووژنى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7226, '1 Samuel 20:3', '1 Samuel', 20, 3, '&nbsp;خو داؤد ورته وفرمائيل، ”ستا پلار ته پته ده چې زۀ ستا څومره خوښ يم او هغۀ دا فېصله کړې ده چې هغه څۀ کول غواړى نو د هغې نه به دې نۀ خبروى، ځکه چې تۀ به سخت خفه شې. زۀ په ژوندى مالِک خُدائ تا ته قسم کوم چې زۀ مرګِ حال يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7227, '1 Samuel 20:4', '1 Samuel', 20, 4, '&nbsp;يونتن ورته ووئيل، ”تۀ چې څۀ هم غواړې نو زۀ به يې کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7228, '1 Samuel 20:5', '1 Samuel', 20, 5, '&nbsp;داؤد ورته وفرمائيل، ”سبا د نوې مياشتې اختر دے او ما له په کار دى چې د بادشاه سره روټۍ وخورم. خو کۀ ستا خوښه وى، نو زۀ به سبا نه بل سبا ماښام پورې په پټو کښې پټ شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7229, '1 Samuel 20:6', '1 Samuel', 20, 6, '&nbsp;خو کۀ ستا پلار ته پته ولګى چې زۀ موجود نۀ يم، نو هغۀ ته ووايه چې ما ستا نه اجازت وغوښتو چې زر زر په بيت‌لحم کښې کور ته لاړ شم، ځکه چې زما د ټولې خاندان دپاره دا د کلنى قربانۍ وخت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7230, '1 Samuel 20:7', '1 Samuel', 20, 7, '&nbsp;کۀ هغه ووائى چې ټيک ده، نو زۀ به بچ شم، خو کۀ هغه غصه شى، نو تا ته به پته ولګى چې هغه ما ته د نقصان رسولو اراده لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7231, '1 Samuel 20:8', '1 Samuel', 20, 8, '&nbsp;مِهربانى وکړه او دا نېکى ما سره وکړه او چې تا د مالِک خُدائ په نوم ما سره کوم تړون کړے دے نو هغه پوره کړه. خو کۀ زۀ ګناهګار يم، نو ما په خپله ووژنه. ما ستا پلار له ولې بوځې چې ومې وژنى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7232, '1 Samuel 20:9', '1 Samuel', 20, 9, '&nbsp;يونتن ورته ووئيل، ”داسې خيال مۀ کوه، کۀ په رښتيا سره ما ته دا پته وے چې زما پلار تا ته د نقصان رسولو اراده لرى، نو ما به تا ته نۀ وئيل څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7233, '1 Samuel 20:10', '1 Samuel', 20, 10, '&nbsp;نو داؤد ترې نه تپوس وکړو، ”تا له چې پلار په غصه کښې جواب درکړى نو ما ته به څنګه پته ولګى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7234, '1 Samuel 20:11', '1 Samuel', 20, 11, '&nbsp;يونتن ورته ووئيل، ”راځه چې پټو ته لاړ شُو.“ نو هغوئ لاړل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7235, '1 Samuel 20:12', '1 Samuel', 20, 12, '&nbsp;او يونتن داؤد ته ووئيل، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک دې زمونږ ګواه وى چې سبا يا بل سبا دا وخت به زۀ د خپل پلار نه تپوس وکړم. کۀ د هغۀ اراده ستا دپاره ښۀ وى نو زۀ به تا خبر کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7236, '1 Samuel 20:13', '1 Samuel', 20, 13, '&nbsp;خو کۀ هغه تا ته د نقصان رسولو اراده لرى، نو مالِک خُدائ دې ما ووژنى کۀ ما تۀ خبر نۀ کړې او بچ مې نۀ کړې. مالِک خُدائ دې ستا مل وى لکه څنګه چې هغه زما د پلار مل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7237, '1 Samuel 20:14', '1 Samuel', 20, 14, '&nbsp;او کۀ زۀ ژوندے پاتې شوم، نو مِهربانى وکړه او خپله مقدسه وعده پوره کړه او زما وفادار اوسه، خو کۀ زۀ مړ شوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7238, '1 Samuel 20:15', '1 Samuel', 20, 15, '&nbsp;نو زما د خاندان سره هم د همېشه دپاره وفادار اوسه. او چې کله مالِک خُدائ ستا ټول دشمنان د زمکې د مخ نه ورک کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7239, '1 Samuel 20:16', '1 Samuel', 20, 16, '&nbsp;نو زمونږ د يو بل سره وعده دې بيا هم نۀ ماتيږى. کۀ دا ماته شى، نو مالِک خُدائ به تا له سزا درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7240, '1 Samuel 20:17', '1 Samuel', 20, 17, '&nbsp;يونتن د داؤد نه يو ځل بيا وعده واخستله چې د هغۀ سره به مينه کوې، ځکه چې يونتن د داؤد سره د خپل ځان په شان مينه کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7241, '1 Samuel 20:18', '1 Samuel', 20, 18, '&nbsp;بيا يونتن هغۀ ته ووئيل، ”سبا د نوې مياشتې اختر دے، کۀ تۀ د روټۍ په دسترخوان باندې نۀ يې نو پته به ولګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7242, '1 Samuel 20:19', '1 Samuel', 20, 19, '&nbsp;سبا نه بل سبا هغه ځائ ته لاړ شه چرته چې تۀ مخکښې پټ شوے وې او د ګټ سره اِنتظار وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7243, '1 Samuel 20:20', '1 Samuel', 20, 20, '&nbsp;بيا به زۀ هغه ګټ په درېو غشو باندې وولم چې دا ګنې نښه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7244, '1 Samuel 20:21', '1 Samuel', 20, 21, '&nbsp;بيا به زۀ خپل نوکر ته ووايم چې لاړ شه او غشى وګوره. او کۀ زۀ هغۀ ته ووايم چې ګوره، غشى ستا دې طرف ته دى، راوايخله، نو د دې مطلب به دا وى چې تۀ بچ يې او بهر راشه. زۀ په ژوندى مالِک خُدائ قسم خورم چې تا ته به هيڅ خطره نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7245, '1 Samuel 20:22', '1 Samuel', 20, 22, '&nbsp;خو کۀ زۀ هغۀ ته ووايم چې وړاندې لاړ شه غشى ستا نه مخکښې دى، نو مطلب به دا وى چې ځان وباسه، ځکه چې مالِک خُدائ تا لېږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7246, '1 Samuel 20:23', '1 Samuel', 20, 23, '&nbsp;د هغې دپاره چې مونږ د يو بل سره وعده کړې ده، نو مالِک خُدائ دې وکړى چې دا وعده مونږ د همېشه دپاره پوره کوُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7247, '1 Samuel 20:24', '1 Samuel', 20, 24, '&nbsp;نو داؤد په پټو کښې پټ شو. او د نوې مياشتې په اختر باندې ساؤل بادشاه روټۍ له راغلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7248, '1 Samuel 20:25', '1 Samuel', 20, 25, '&nbsp;او د دېوال سره په خپل ځائ باندې کښېناستو. ابنير ورسره کښېناستو او يونتن ورته مخامخ کښېناستو. او د داؤد ځائ خالى وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7249, '1 Samuel 20:26', '1 Samuel', 20, 26, '&nbsp;خو ساؤل په هغه ورځ باندې هيڅ هم ونۀ وئيل، ځکه چې د هغۀ خيال دا وو چې هغه د څۀ وجې نه پليت شوے دے او هغه بې‌شکه ناپاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7250, '1 Samuel 20:27', '1 Samuel', 20, 27, '&nbsp;په بله ورځ، د نوې مياشتې اختر پسې ورځ باندې، د داؤد ځائ بيا هم خالى وو او ساؤل د يونتن نه تپوس وکړو، ”داؤد ولې نۀ پرون روټۍ له راغلے وو او نۀ نن راغلو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7251, '1 Samuel 20:28', '1 Samuel', 20, 28, '&nbsp;يونتن جواب ورکړو، ”هغۀ ما ته سوال وکړو چې هغه پرېږدم چې بيت‌لحم ته لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7252, '1 Samuel 20:29', '1 Samuel', 20, 29, '&nbsp;هغۀ ووئيل چې مِهربانى وکړه او ما پرېږده چې لاړ شم ځکه چې زمونږ خاندان په ښار کښې قربانى کوى او ورور مې حُکم راکړو چې هلته موجود شه. کۀ تۀ زما نه خوشحال يې نو ما پرېږده چې زما خپلوان وګورم. نو دا وجه ده چې هغه ستا په دسترخوان باندې په خپل ځائ باندې نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7253, '1 Samuel 20:30', '1 Samuel', 20, 30, '&nbsp;ساؤل يونتن ته سخت غصه وو او ورته يې ووئيل، ”تۀ د يوې سرکشې او بې‌وفا ښځې زوئ يې. اوس ما ته دا پته ده چې تۀ د داؤد ملګرتيا کوې او د خپلې مور او د خپل ځان بې‌عزتى کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7254, '1 Samuel 20:31', '1 Samuel', 20, 31, '&nbsp;تا ته دا پته نۀ لګى څۀ چې تر کومې پورې داؤد ژوندے وى، نو تۀ به هيڅکله د دې مُلک بادشاه نۀ شې؟ اوس لاړ شه او هغه دلته راوله، هغه به خامخا وژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7255, '1 Samuel 20:32', '1 Samuel', 20, 32, '&nbsp;يونتن جواب ورکړو، ”هغه به ولې مرى؟ هغۀ څۀ کړى دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7256, '1 Samuel 20:33', '1 Samuel', 20, 33, '&nbsp;او په دې ساؤل خپله نېزه په يونتن ورګزار کړه چې وې وژنى او يونتن ته پته ولګېده چې پلار يې په رښتيا سره د داؤد د وژلو اراده لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7257, '1 Samuel 20:34', '1 Samuel', 20, 34, '&nbsp;نو يونتن په غصه کښې د دسترخوان نه پاڅېدو او په هغه ورځ يې هيڅ هم ونۀ خوړل چې د نوې مياشتې د اختر دوېمه ورځ وه. هغه ډېر زيات خفه وو ځکه چې د هغۀ پلار ساؤل د داؤد بې‌عزتى کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7258, '1 Samuel 20:35', '1 Samuel', 20, 35, '&nbsp;په ورپسې سحر يونتن پټو ته لاړو چې د داؤد سره مِلاو شى، لکه چې څنګه هغوئ دا وخت مقرر کړے وو. او د ځان سره يې يو هلک هم بوتلو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7259, '1 Samuel 20:36', '1 Samuel', 20, 36, '&nbsp;او هغۀ ته يې ووئيل، ”منډه کړه او چې زۀ کوم غشى ولم نو هغه لټوه.“ هلک منډه کړه او يونتن د هغۀ نه مخکښې يو غشے وويشتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7260, '1 Samuel 20:37', '1 Samuel', 20, 37, '&nbsp;کله چې هلک هغه ځائ ته ورسېدو چرته چې غشے غورزېدلے وو، نو يونتن ورته آواز وکړو، ”غشے نور هم مخکښې دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7261, '1 Samuel 20:38', '1 Samuel', 20, 38, '&nbsp;دلته مۀ ايسارېږه، زر زر لاړ شه.“ نو هلک غشے راواخستلو او خپل نېک ته راواپس شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7262, '1 Samuel 20:39', '1 Samuel', 20, 39, '&nbsp;او د دې پته ورته نۀ وه چې د دې مطلب څۀ دے، صِرف يونتن او داؤد ته پته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7263, '1 Samuel 20:40', '1 Samuel', 20, 40, '&nbsp;يونتن خپله وسله هلک له ورکړه او ورته يې ووئيل چې دا ښار ته واپس يوسه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7264, '1 Samuel 20:41', '1 Samuel', 20, 41, '&nbsp;کله چې هلک لاړو، نو داؤد د ګټ د شا نه راپاڅېدو، هغه پړمخې په زمکه پرېوتو او درې ځل ورته د عزت نه ټيټ شو. کله چې هغوئ يو بل ښکلول نو هغۀ او يونتن دواړو ژړل، د داؤد خفګان د يونتن نه هم زيات وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7265, '1 Samuel 20:42', '1 Samuel', 20, 42, '&nbsp;بيا يونتن داؤد ته ووئيل، ”په خېر سره لاړ شه، مالِک خُدائ دې وکړى چې زما او ستا او زما او ستا د اولاد تر مينځه هغه مقدسه وعده قائمه وى چې مونږ د يو بل سره کړې ده.“ بيا داؤد لاړو او يونتن ښار ته واپس شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7266, '1 Samuel 21:1', '1 Samuel', 21, 1, '&nbsp;داؤد په نوب کښې اخيمُلک اِمام له لاړو. اخيمُلک ورله مِلاوېدو دپاره د يرې نه په ريږدېدو راووتلو او تپوس يې ترې نه وکړو، ”تۀ يواځې ولې يې او چې يو کس هم درسره نشته؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7267, '1 Samuel 21:2', '1 Samuel', 21, 2, '&nbsp;داؤد جواب ورکړو، ”زۀ د بادشاه د يو کار دپاره دلته راغلے يم، هغۀ ما ته وئيلى دى چې هيچا ته پته ونۀ لګى چې زۀ هغۀ د څۀ دپاره رالېږلے يم. ما خپلو فوجيانو ته وئيلى دى چې په يو بل ځائ کښې زما سره مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7268, '1 Samuel 21:3', '1 Samuel', 21, 3, '&nbsp;تا سره د خوراک څۀ شته؟ ما له پينځۀ روټۍ راکړه يا کۀ نور څۀ درسره وى نو رايې کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7269, '1 Samuel 21:4', '1 Samuel', 21, 4, '&nbsp;اِمام ورته ووئيل، ”زما سره صِرف مقدسه روټۍ ده، عامه روټۍ راسره نشته، کۀ ستا سړو په دې نزدې وخت کښې ځان د ښځو نه ساتلے وى نو تاسو دا خوړے شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7270, '1 Samuel 21:5', '1 Samuel', 21, 5, '&nbsp;داؤد جواب ورکړو، ”بې‌شکه، دوئ ځان ساتلے دے، زما سړى همېشه خپل ځانونه پاک ساتى تر دې پورې کۀ هغوئ په يو عام کار پسې هم ځى، او نن مونږ څومره په خاص کار پسې راوتلى يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7271, '1 Samuel 21:6', '1 Samuel', 21, 6, '&nbsp;نو اِمام داؤد له مقدسه روټۍ ورکړه، ځکه چې د هغۀ سره صِرف هم هغه روټۍ وه چې کومه مالِک خُدائ ته پېش کړے شوې وه، کومه چې د مقدس مېز نه لرې کړے شوې وه او د هغې په ځائ تازه روټۍ اېښے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7272, '1 Samuel 21:7', '1 Samuel', 21, 7, '&nbsp;نو د ساؤل مشر شپون دوئيګ ادومے په هغه ورځ د مالِک خُدائ په حضور کښې د عبادت دپاره ايسار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7273, '1 Samuel 21:8', '1 Samuel', 21, 8, '&nbsp;داؤد اخيمُلک ته وفرمائيل، ”تا سره نېزه يا تُوره شته؟ د بادشاه د حُکم په وجه زۀ دومره په تېزۍ لاړم چې ما ته دومره وخت هم مِلاو نۀ شو چې زۀ خپله تُوره يا بل څۀ راواخلم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7274, '1 Samuel 21:9', '1 Samuel', 21, 9, '&nbsp;اخيمُلک ورته ووئيل، ”زما سره د فلستى جوليت تُوره ده، کوم چې تا د ايله په مېدان کښې وژلے وو، د دې پېش بند نه وروستو په کپړه کښې تاو ده. کۀ تۀ غواړې نو راوايخله، صِرف هم دغه يوه وسله شته.“ داؤد ورته وفرمائيل، ”رايې کړه. د دې نه ښۀ وسله نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7275, '1 Samuel 21:10', '1 Samuel', 21, 10, '&nbsp;نو داؤد هلته نه لاړو او د ساؤل نه وتښتېدو او د جات بادشاه اکيس له لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7276, '1 Samuel 21:11', '1 Samuel', 21, 11, '&nbsp;د بادشاه آفسرانو اکيس ته ووئيل، ”دا هغه داؤد نۀ دے څۀ، کوم چې د خپل مُلک بادشاه دے؟ دا هغه سړے دے چې کله ښځې ګډېدې نو په سندرو کښې يې وئيل چې ساؤل زرګونه وژلى دى، خو داؤد يو په لس د هغې نه زيات وژلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7277, '1 Samuel 21:12', '1 Samuel', 21, 12, '&nbsp;د هغوئ خبرو په داؤد باندې ډېر زيات اثر وکړو او هغه د جات اکيس بادشاه نه ډېر زيات ويرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7278, '1 Samuel 21:13', '1 Samuel', 21, 13, '&nbsp;نو چې کله هغوئ هلته وُو، داؤد به خپل چال چلن بدلولو او چې کله به هغوئ ورته کتل نو د ځان نه به يې ليونے جوړولو، هغۀ به د ښار په دروازو کرښې وهلې او په ږيره به يې لاړې بهېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7279, '1 Samuel 21:14', '1 Samuel', 21, 14, '&nbsp;نو اکيس خپلو آفسرانو ته ووئيل، ”ګورئ، هغه سړے ليونے دے. دا مو ما له ولې راوستلو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7280, '1 Samuel 21:15', '1 Samuel', 21, 15, '&nbsp;مونږ سره د ليونو کمے نشته نو بيا زۀ ولې دے په خپل کور کښې پرېږدم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7281, '1 Samuel 22:1', '1 Samuel', 22, 1, '&nbsp;داؤد د جات ښار نه وتښتېدو او د عدولام ښار ته نزدې يو غار ته لاړو. کله چې د هغۀ وروڼه او نور خاندان خبر شو چې هغه هلته دے، نو هغوئ ورسره مِلاو شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7282, '1 Samuel 22:2', '1 Samuel', 22, 2, '&nbsp;کوم خلق چې په تکليف کښې وُو، قرضدارى وُو يا خفه وُو نو هغوئ ورغلل، دا تقريباً ټول څلور سوه سړى وُو او هغه د هغوئ مشر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7283, '1 Samuel 22:3', '1 Samuel', 22, 3, '&nbsp;داؤد د هغه ځائ نه په موآب کښې مصفاه ته لاړو او د موآب بادشاه ته يې ووئيل، ”بادشاه سلامت زما مور او پلار پرېږده چې راشى او تا سره تر هغې پورې ايسار وى چې ما ته پته ولګى چې خُدائ پاک به زما دپاره څۀ کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7284, '1 Samuel 22:4', '1 Samuel', 22, 4, '&nbsp;نو داؤد خپل مور پلار د موآب بادشاه سره پرېښودل او چې کله داؤد په محفوظ ځائ کښې پټ وو نو هغوئ هلته ايسار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7285, '1 Samuel 22:5', '1 Samuel', 22, 5, '&nbsp;بيا جاد پېغمبر داؤد له راغلو او ورته يې وفرمائيل، ”دلته مۀ ايسارېږه، او سمدستى د يهوداه مُلک ته لاړ شه.“ نو داؤد روان شو او د حارت ځنګل ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7286, '1 Samuel 22:6', '1 Samuel', 22, 6, '&nbsp;يوه ورځ ساؤل په جبعه کښې په غرۀ باندې د غز د ونې لاندې ناست وو، نېزه يې په لاس کښې وه او خپل ټول آفسران ترې نه ګېرچاپېره ولاړ وُو. هغه خبر شو چې داؤد او د هغۀ سړى پېدا شوى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7287, '1 Samuel 22:7', '1 Samuel', 22, 7, '&nbsp;نو هغۀ خپلو آفسرانو ته ووئيل، ”د بنيامين سړو غوږ ونيسئ. ستاسو خيال دا دے څۀ چې داؤد به تاسو ټولو له پټى او د انګورو باغونه درکړى؟ او د خپل لښکر آفسران به مو جوړ کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7288, '1 Samuel 22:8', '1 Samuel', 22, 8, '&nbsp;هم دغه وجه ده څۀ چې تاسو زما خِلاف منصوبه جوړَوئ؟ ستاسو نه يو کس هم ما ته ونۀ وئيل چې زما خپل زوئ د داؤد سره اِتحاد کړے دے. هيچا سره زما فکر نشته او نۀ ما ته وائى چې زما خپل سړے يعنې داؤد په دې منصوبه کښې لګيا دے چې زما د وژلو موقع لټوى او زما خپل زوئ د هغۀ ډاډګيرنه کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7289, '1 Samuel 22:9', '1 Samuel', 22, 9, '&nbsp;دوئيګ ادومے هلته د ساؤل آفسرانو سره ولاړ وو او وې وئيل، ”کله چې داؤد په نوب کښې د اخيطوب زوئ اخيمُلک له تلو نو هغه ما وليدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7290, '1 Samuel 22:10', '1 Samuel', 22, 10, '&nbsp;اخيمُلک د مالِک خُدائ نه تپوس وکړو چې داؤد څۀ وکړى او بيا هغۀ داؤد له خوراک او د جوليت فلستى تُوره ورکړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7291, '1 Samuel 22:11', '1 Samuel', 22, 11, '&nbsp;نو ساؤل بادشاه اخيمُلک اِمام او د هغۀ ټول خپلوان راوغوښتل، کوم چې په نوب کښې اِمامان وُو او هغوئ ورله راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7292, '1 Samuel 22:12', '1 Samuel', 22, 12, '&nbsp;ساؤل اخيمُلک ته ووئيل، ”اخيمُلکه، خبره واوره.“ نو هغۀ ورته وفرمائيل، ”بادشاه سلامت وايه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7293, '1 Samuel 22:13', '1 Samuel', 22, 13, '&nbsp;ساؤل ترې نه تپوس وکړو، ”تۀ او د يَسى زوئ زما خِلاف ولې منصوبه جوړَوئ؟ تاسو هغۀ له خوراک او تُوره ولې ورکړه او د هغۀ دپاره مو د خُدائ پاک سره مشوره ولې وکړه؟ نو هغۀ زما خِلاف سرکشى وکړه او هغۀ زما خِلاف نن لاره نيولې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7294, '1 Samuel 22:14', '1 Samuel', 22, 14, '&nbsp;اخيمُلک ورته وفرمائيل، ”ستا په ټولو نوکرانو کښې د داؤد په شان وفادار څوک دے؟ هغه د بادشاه زوم دے، ستا د ټولو محافظانو فوجيانو مشر دے او ستا په دربار کښې ډېر زيات عزتمند دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7295, '1 Samuel 22:15', '1 Samuel', 22, 15, '&nbsp;آو، ما څو ځلې د هغۀ دپاره د خُدائ پاک سره مشوره کړې ده، نو بادشاه سلامت، تۀ د دې خبرې اِلزام په ما او زما په خاندان مۀ لګوه. زۀ ستا خِلاف د يوې منصوبې نه هم نۀ وم خبر. د دې خبرې نه، زۀ بېخى خبر نۀ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7296, '1 Samuel 22:16', '1 Samuel', 22, 16, '&nbsp;بادشاه ورته ووئيل، ”اخيمُلکه، تۀ او ستا ټول خپلوان به وژلے شې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7297, '1 Samuel 22:17', '1 Samuel', 22, 17, '&nbsp;د هغۀ سره نزدې چې کوم د هغۀ محافظان ولاړ وُو نو هغوئ ته يې ووئيل، ”د مالِک خُدائ اِمامان ووژنئ. هغوئ د داؤد سره سازش وکړو او ما ته يې ونۀ وئيل چې هغه تښتېدلے دے، اګر چې دې ټولو ته پته ده.“ خو د هغۀ حِفاظت کوونکو د مالِک خُدائ د اِمامانو د وژلو دپاره په هغوئ باندې لاس اوچتولو نه اِنکار وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7298, '1 Samuel 22:18', '1 Samuel', 22, 18, '&nbsp;نو ساؤل دوئيګ ته ووئيل، ”تۀ هغوئ ووژنه.“ او دوئيګ هغوئ ټول ووژل. په هغه ورځ باندې هغۀ پينځۀ اتيا اِمامان ووژل کوم چې د پېش بند د وړلو حقدار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7299, '1 Samuel 22:19', '1 Samuel', 22, 19, '&nbsp;ساؤل دا حُکم هم وکړو چې د اِمامانو د ښار نوب ټول اوسېدونکى دې ووژلے شى، ښځې او سړى، ماشومان او تى رودونکى ماشومان، څاروى، خرۀ او ګډې، هر څۀ ووژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7300, '1 Samuel 22:20', '1 Samuel', 22, 20, '&nbsp;خو د اخيمُلک يو زوئ ابياتار وتښتېدو، لاړو او د داؤد سره مِلاو شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');